CREATE OR ALTER PROCEDURE [COMERCIAL].[SP_LISTA_PRECIO_PRODUCTO_SAVE]
    @I_ID_LISTA_PRECIO_PRODUCTO BIGINT = NULL, @I_ID_EMPRESA BIGINT, @I_ID_LISTA_PRECIO BIGINT, @I_ID_PRODUCTO BIGINT, @I_PRECIO_UNITARIO DECIMAL(19,4), @I_CODIGO_ESTADO NVARCHAR(30), @I_ROW_VERSION BINARY(8) = NULL,
    @S_ID_SESION BIGINT, @S_ID_USUARIO BIGINT, @O_ID_LISTA_PRECIO_PRODUCTO BIGINT OUTPUT, @O_CODIGO_ERROR BIGINT OUTPUT, @O_MENSAJE NVARCHAR(4000) OUTPUT, @O_FILAS_AFECTADAS INT OUTPUT
AS
BEGIN
    SET NOCOUNT ON; SET @O_CODIGO_ERROR = NULL; SET @O_MENSAJE = NULL; SET @O_FILAS_AFECTADAS = 0;
    IF @I_PRECIO_UNITARIO < 0 OR @I_CODIGO_ESTADO NOT IN (N'ACTIVO', N'INACTIVO') THROW 50000, 'El precio y el estado deben ser válidos.', 1;
    IF NOT EXISTS (SELECT 1 FROM [COMERCIAL].[LISTAS_PRECIOS] WHERE [ID_LISTA_PRECIO] = @I_ID_LISTA_PRECIO AND [ID_EMPRESA] = @I_ID_EMPRESA) OR NOT EXISTS (SELECT 1 FROM [INVENTARIO].[PRODUCTOS] WHERE [ID_PRODUCTO] = @I_ID_PRODUCTO AND [ID_EMPRESA] = @I_ID_EMPRESA) THROW 50001, 'La lista o el producto no pertenece a la empresa.', 1;
    IF @I_ID_LISTA_PRECIO_PRODUCTO IS NULL BEGIN INSERT INTO [COMERCIAL].[LISTAS_PRECIOS_PRODUCTOS] ([ID_LISTA_PRECIO], [ID_PRODUCTO], [PRECIO_UNITARIO], [CODIGO_ESTADO], [ID_USUARIO_ALTA]) VALUES (@I_ID_LISTA_PRECIO, @I_ID_PRODUCTO, @I_PRECIO_UNITARIO, @I_CODIGO_ESTADO, @S_ID_USUARIO); SET @O_ID_LISTA_PRECIO_PRODUCTO = CONVERT(BIGINT, SCOPE_IDENTITY()); SET @O_FILAS_AFECTADAS = 1; RETURN; END;
    UPDATE [LPP] SET [PRECIO_UNITARIO] = @I_PRECIO_UNITARIO, [CODIGO_ESTADO] = @I_CODIGO_ESTADO, [FECHA_MODIFICACION_UTC] = SYSUTCDATETIME(), [ID_USUARIO_MODIFICACION] = @S_ID_USUARIO FROM [COMERCIAL].[LISTAS_PRECIOS_PRODUCTOS] AS [LPP] INNER JOIN [COMERCIAL].[LISTAS_PRECIOS] AS [LIS] ON [LIS].[ID_LISTA_PRECIO] = [LPP].[ID_LISTA_PRECIO] WHERE [LPP].[ID_LISTA_PRECIO_PRODUCTO] = @I_ID_LISTA_PRECIO_PRODUCTO AND [LIS].[ID_EMPRESA] = @I_ID_EMPRESA AND [LPP].[ROW_VERSION] = @I_ROW_VERSION;
    SET @O_FILAS_AFECTADAS = @@ROWCOUNT; SET @O_ID_LISTA_PRECIO_PRODUCTO = @I_ID_LISTA_PRECIO_PRODUCTO; IF @O_FILAS_AFECTADAS = 0 BEGIN SET @O_CODIGO_ERROR = 40007; SET @O_MENSAJE = N'El precio fue modificado por otro usuario o no pertenece a la empresa.'; END;
END;
